package settings

import "strings"

// Load parses KEY=VALUE lines into a map. Lines without '=' are ignored.
func Load(lines []string) map[string]string {
	values := map[string]string{}
	for _, line := range lines {
		key, value, found := strings.Cut(line, "=")
		if found {
			values[strings.TrimSpace(key)] = strings.TrimSpace(value)
		}
	}
	return values
}

