package server

// Listener is where the HTTP server will bind.
type Listener struct {
	addr string
}

// NewListener reads HOST and PORT out of the loaded settings.
func NewListener(values map[string]string) Listener {
	return Listener{addr: values["HOST"] + ":" + values["PORT"]}
}

// Addr answers the bind address as host:port.
func (l Listener) Addr() string {
	return l.addr
}
